    iron_inkwellstopper = { name = "Železni zamašek za črnilnico", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni zamašek za črnilnico za pisarje." },
    bronze_inkwellstopper = { name = "Bronast zamašek za črnilnico", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zamašek za črnilnico za pisarje." },
    silver_inkwellstopper = { name = "Srebrn zamašek za črnilnico", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zamašek za črnilnico za pisarje." },
    gilded_inkwellstopper = { name = "Pozlačen zamašek za črnilnico", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen zamašek za črnilnico za pisarje." },
    jewel_set_inkwellstopper = { name = "Draguljast zamašek za črnilnico", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zamašek za črnilnico za pisarje." },
    royal_sovereign_inkwellstopper = { name = "Kraljevski suveren zamašek za črnilnico", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren zamašek za črnilnico z biseri za krono." },
}
local BUILDINGS = {
    inkwellstopper_workshop = { name = "Inkwellstopper delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
