    master_inkwellstopper_atelier = { name = "Mojstrski inkwellstopper atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_inkwellstopper_palace = { name = "Suverena inkwellstopper palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
InkwellStopperMaker.ironStock=14; InkwellStopperMaker.bronzeStock=10; InkwellStopperMaker.woodStock=14; InkwellStopperMaker.leatherStock=10; InkwellStopperMaker.silverStock=8; InkwellStopperMaker.goldStock=6; InkwellStopperMaker.jewelStock=4; InkwellStopperMaker.pearlStock=4
InkwellStopperMaker.productStock = {}; InkwellStopperMaker.buildings = {}; InkwellStopperMaker.maker = nil; InkwellStopperMaker.activeMaking = {}; InkwellStopperMaker.totalProducts = 0; InkwellStopperMaker.dayTimer = 0
function InkwellStopperMaker.init() InkwellStopperMaker.ironStock=14; InkwellStopperMaker.bronzeStock=10; InkwellStopperMaker.woodStock=14; InkwellStopperMaker.leatherStock=10; InkwellStopperMaker.silverStock=8; InkwellStopperMaker.goldStock=6; InkwellStopperMaker.jewelStock=4; InkwellStopperMaker.pearlStock=4; InkwellStopperMaker.productStock={}; InkwellStopperMaker.buildings={}; InkwellStopperMaker.maker=nil; InkwellStopperMaker.activeMaking={}; InkwellStopperMaker.totalProducts=0; InkwellStopperMaker.dayTimer=0; print("[InkwellStopperMaker] Royal Inkwell Stopper Maker System initialized (6 products, 4 buildings)") end
function InkwellStopperMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; InkwellStopperMaker.maker={name=n or ("Zamaškar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zamaškar najet: %s (spretnost: %d)",InkwellStopperMaker.maker.name,s),"success") end; return true end
function InkwellStopperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function InkwellStopperMaker.build(id) local ok,e=InkwellStopperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(InkwellStopperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function InkwellStopperMaker.getQualityBonus() local b=0; for _,bd in ipairs(InkwellStopperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function InkwellStopperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and InkwellStopperMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and InkwellStopperMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and InkwellStopperMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and InkwellStopperMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and InkwellStopperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and InkwellStopperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and InkwellStopperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and InkwellStopperMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #InkwellStopperMaker.buildings==0 then return false,"Potrebna zamašna delavnica" end; if not InkwellStopperMaker.maker then return false,"Potreben zamaškar" end; return true end
function InkwellStopperMaker.make(pt,qty) qty=qty or 1; local ok,e=InkwellStopperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then InkwellStopperMaker.ironStock=InkwellStopperMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then InkwellStopperMaker.bronzeStock=InkwellStopperMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then InkwellStopperMaker.woodStock=InkwellStopperMaker.woodStock-d.woodCost*qty end; if d.leatherCost then InkwellStopperMaker.leatherStock=InkwellStopperMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then InkwellStopperMaker.silverStock=InkwellStopperMaker.silverStock-d.silverCost*qty end; if d.goldCost then InkwellStopperMaker.goldStock=InkwellStopperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then InkwellStopperMaker.jewelStock=InkwellStopperMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then InkwellStopperMaker.pearlStock=InkwellStopperMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if InkwellStopperMaker.maker then t=math.max(1,t-math.floor(InkwellStopperMaker.maker.skill/13)) end; table.insert(InkwellStopperMaker.activeMaking,{id="inkwellstopper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function InkwellStopperMaker.completeMaking(m) local q=1.0+(InkwellStopperMaker.getQualityBonus()/100); if InkwellStopperMaker.maker then q=q+(InkwellStopperMaker.maker.skill/140) end; q=math.min(2.5,q); InkwellStopperMaker.productStock[m.productType]=(InkwellStopperMaker.productStock[m.productType] or 0)+m.quantity; InkwellStopperMaker.totalProducts=InkwellStopperMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if InkwellStopperMaker.maker then InkwellStopperMaker.maker.itemsMade=InkwellStopperMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then InkwellStopperMaker.maker.skill=math.min(100,InkwellStopperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zamašek izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"inkwellstopper.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function InkwellStopperMaker.update(dt) if not _G.state then return end; InkwellStopperMaker.dayTimer=InkwellStopperMaker.dayTimer+dt; if InkwellStopperMaker.dayTimer>=30 then InkwellStopperMaker.dayTimer=0; for i=#InkwellStopperMaker.activeMaking,1,-1 do local m=InkwellStopperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then InkwellStopperMaker.completeMaking(m); table.remove(InkwellStopperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(InkwellStopperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if InkwellStopperMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function InkwellStopperMaker.getStats() return {ironStock=InkwellStopperMaker.ironStock,bronzeStock=InkwellStopperMaker.bronzeStock,woodStock=InkwellStopperMaker.woodStock,leatherStock=InkwellStopperMaker.leatherStock,silverStock=InkwellStopperMaker.silverStock,goldStock=InkwellStopperMaker.goldStock,jewelStock=InkwellStopperMaker.jewelStock,pearlStock=InkwellStopperMaker.pearlStock,productStock=InkwellStopperMaker.productStock,numBuildings=#InkwellStopperMaker.buildings,hasMaker=InkwellStopperMaker.maker~=nil,makerName=InkwellStopperMaker.maker and InkwellStopperMaker.maker.name or "—",makerSkill=InkwellStopperMaker.maker and InkwellStopperMaker.maker.skill or 0,activeMaking=#InkwellStopperMaker.activeMaking,totalProducts=InkwellStopperMaker.totalProducts} end
return InkwellStopperMaker
